use std::fs

fn parse_line(line: string) -> Vec<string> {
    let chars: Vec<char> = line.chars().collect()
    let n = chars.len()
    let mut fields: Vec<string> = []
    let mut cur = ""
    let mut in_q = false
    let mut i = 0
    while i < n {
        let c = chars[i]
        if in_q {
            if c == '"' {
                if i + 1 < n && chars[i + 1] == '"' {
                    cur.push('"')
                    i += 1
                } else {
                    in_q = false
                }
            } else {
                cur.push(c)
            }
        } else if c == '"' {
            in_q = true
        } else if c == ',' {
            fields.push(cur)
            cur = ""
        } else {
            cur.push(c)
        }
        i += 1
    }
    fields.push(cur)
    fields
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let fields = parse_line(line)
        let parts: Vec<string> = fields.map(|f| "[${f}]").collect()
        println("${fields.len()}: ${parts.join("|")}")
    }
}

